"""Create the fixed scenario curriculum once; no model calls or training."""
from pathlib import Path
import json,random,collections,hashlib
root=Path(__file__).resolve().parents[1]
if (root/'data/author-only-v1/scenario-plan.json').exists():raise RuntimeError('Frozen plan exists; do not overwrite an active generation job')
src=root/'data/conversations-v1/authored-200.jsonl';old=[json.loads(x) for x in src.read_text().splitlines()];assert len(old)==200
mapping={'small_talk':'everyday','everyday_planning':'everyday','preferences':'everyday','context_followup':'followup','corrections':'followup','explanations':'explanation','learning':'explanation','simple_reasoning':'explanation','writing':'writing','clarification':'clarification','honesty':'clarification','required_repetition':'instruction'}
counts=collections.Counter(mapping[x['category']] for x in old)
targets={'everyday':3000,'followup':2000,'explanation':2000,'writing':1500,'clarification':1000,'instruction':500}
topics={
'everyday':'''organizing a bookshelf|a quiet weekend at home|choosing a screen-free hobby|a short visit from a friend|packing for a casual trip|keeping a shared room tidy|taking a library book back|choosing a notebook|making time for reading|planning a small gathering|finding lost keys|remembering errands|sorting photographs|preparing for a rainy day|choosing a place to sit and read|arranging a walk with a friend|handling a cancelled plan|a first attempt at sketching|finishing a puzzle|visiting a local museum|keeping a simple diary|starting a collection of postcards|a modest gift for a neighbor|organizing craft supplies|choosing between indoor activities|arranging shared chores|making a small workspace comfortable|finding a bookmark|remembering a borrowed item|planning a quiet evening|dealing with a delayed reply|welcoming a new neighbor|sorting a crowded drawer|choosing a group activity|setting aside time for a personal project|reducing distractions while reading|organizing a bag|enjoying a free afternoon|revisiting a forgotten hobby|choosing pictures for a wall|a relaxed family visit|collecting a repaired item|making a list of household tasks|organizing paper notes|planning a game evening|keeping track of a borrowed book|choosing a creative activity with little equipment|planning a short solo outing|tidying one corner of a room|taking a break between tasks|preparing a guest sleeping space|deciding what to keep on a desk|sorting unused stationery|setting up a simple weekly routine|making a shared shopping list without dietary advice|choosing an activity for a small group|taking care of a favorite piece of clothing|arranging a book exchange|starting a sketchbook|choosing a quiet social plan''',
'followup':'''revising a weekend plan after a timing change|correcting the number of visitors|changing an invitation from formal to casual|remembering two preferences across turns|changing a destination while keeping the date|correcting a person's name in a draft|changing a gift budget|switching an activity because of rain|adjusting a plan for limited space|remembering which option the user rejected|distinguishing two borrowed books|clarifying an ambiguous pronoun|revising a packing list for a shorter trip|correcting a mistaken quantity|changing a meeting time|switching from a group outing to a solo plan|updating a task list after one task is done|keeping a constraint while changing the goal|revising a message after an address correction|tracking two people's availability|summarizing only information supplied in the chat|helping with a hobby after the user rules out equipment|changing a writing tone without changing facts|remembering a preferred color|revising a plan when a friend cannot attend|correcting the order of two tasks|helping find an object from clues supplied by the user|keeping track of a returned item|resolving a misunderstanding politely|adapting an explanation after the user asks for less detail|changing a deadline in a draft|updating an event location supplied by the user|comparing two options after a new preference|keeping a fictional name consistent|answering a follow-up about a previous example|revising a schedule after a cancelled appointment|changing one sentence while preserving the rest|acknowledging a correction without excessive apology|distinguishing a new request from the previous one|keeping track of who borrowed what''',
'explanation':'''the difference between a map and a photograph|why shadows change length|why a wet towel dries|how echoes happen|what a calendar is for|the difference between a browser tab and a window|the difference between storage and RAM|why changing a file extension does not convert a file|the difference between a backup and synchronization|how a simple map scale works|what an average describes|how to compare simple fractions|why a square is a rectangle|the difference between a question and a statement|how an index helps find information|what a table of contents does|how alphabetical sorting works|the difference between a draft and a final copy|why reading aloud can reveal awkward wording|the difference between a fact and an opinion|what a synonym is|what an antonym is|the difference between a summary and a quotation|how to break a task into smaller steps|how to explain an idea in one's own words|the difference between an example and a definition|why a plan may need spare time|how to estimate without claiming an exact answer|the difference between area and perimeter|how to count inclusive page ranges|how to work out elapsed time on the same day|how to split a small whole-number cost equally|how to check a simple multiplication result|how to track items remaining after removing some|how to compare amounts with the same units|what a pattern is|why repeated practice can help a skill|how to ask for specific feedback|the difference between revising and proofreading|how to learn from a worked example|what a label is useful for|why an unfamiliar word needs context|how to use a glossary|the difference between a schedule and a checklist|how to explain a process with a simple sequence|why instructions need clear references|the difference between an observation and a guess|how to organize a short explanation|how to notice a missing assumption|why more detail is not always clearer''',
'writing':'''a short thank-you note|a friendly invitation|a message about arriving late|a request to return a borrowed item|a reminder about an agreed time|a polite decline without an invented excuse|a request to reschedule|a message asking for a missing attachment|a clearer notice for a shared space|a concise event announcement|a simple birthday greeting|a note to a new neighbor|a request for missing directions|a message about a lost umbrella|an apology for a delayed reply|a request for a clearer explanation|a short update on a personal project|a reminder to close a gate|a change of venue supplied by the user|a cancellation message|a request to confirm attendance|a note about a found object|a brief request for feedback|a less abrupt wording of a request|a casual version of a formal sentence|a clearer subject line|removing filler words from a sentence|splitting a long sentence in two|combining two short sentences|preserving names and numbers during editing|replacing an unclear pronoun|reordering a message for clarity|writing a polite boundary|correcting a simple grammatical error|turning a vague request into a specific one|making a greeting warmer without adding facts|a brief note for a parcel|a request to change a collection time|a caption for a photo described by the user|a short introduction to a hobby group|a note to a book club|asking permission to borrow something|a message returning a lost item|a clear instruction for using shared supplies|a short description of a room supplied by the user''',
'clarification':'''an unspecified item to shorten|an ambiguous date format|a missing destination|a question with unclear units|two possible meanings of a word|a comparison without named options|a request to summarize an unavailable document|a question about an unseen picture|a missing event time|a request to remember information never supplied|a question about current weather without a source|a request to send a message with no messaging tool|a request to book something without a booking tool|an unknown opening time|an unspecified audience for an explanation|a request to organize unnamed items|a pronoun with two plausible referents|a missing starting time for a duration question|a question about a person's private thoughts|a request to identify an object from too few details|a request for an exact price without a listing|an unclear writing tone|a request to copy text that was not supplied|an unspecified sort order|a missing number in a simple calculation|an unavailable personal schedule|a request to inspect a room without a photo|an incomplete address-formatting question|a question about an unverified quotation|an unclear goal for a plan|a question about the assistant's personal experiences|a request to confirm an action not actually performed|an ambiguous quantity of people|a question requiring information from a previous unavailable chat|a request to guess while clearly labelling the guess''',
'instruction':'''copy a short sentence exactly including deliberate repeated words|repeat a short word a stated small number of times|keep a repeated number when copying a list|change only one word in a sentence|preserve the same name twice in a sentence|answer in two short bullet points|give one short sentence and then shorten it|use only facts in a small user-provided note|keep a quoted phrase unchanged while changing surrounding text|follow an explicit request to repeat a previous answer|use a specified word naturally in a short reply|return a tiny list in the user's specified order|alphabetize three familiar words|copy a simple label on two lines|retain duplicates when the user requests exact copying|remove duplicates only when explicitly requested|keep a user-supplied capitalization pattern|write a sentence in lowercase when asked|omit an explanation when the user asks for just the answer|explain why deliberate repetition can be useful'''
}
# These specify scenarios, not response templates. The local teacher writes every message.
settings=['at home','in a shared flat','during a quiet afternoon','while preparing for a visit','between ordinary daily tasks','during a weekend','while making a small plan','in a library-related setting','before a casual gathering','while organizing personal belongings','during an exchange with a friend','in a learning setting']
styles=['brief and direct','warm but not overly enthusiastic','plain informal English','calm and practical','curious and conversational','concise with a useful example','matter-of-fact without robotic phrasing']
angles=['The user supplies one concrete detail naturally.','The user has limited time.','The user changes a preference in the follow-up.','The user needs a small manageable first step.','The user asks a specific follow-up rather than merely saying thanks.','The user explains why a previous option will not work.','The user prefers a simple answer over a list.','The user corrects one harmless detail.','The user asks for a different wording.','The user adds a practical constraint.','The user asks how the idea applies to their case.','The user is uncertain and asks a modest question.','The user wants an example before deciding.','The user compares two reasonable options.']
rng=random.Random(20261031);tasks=[]
for category,target in targets.items():
 ts=topics[category].split('|')
 for i in range(target-counts[category]):
  tasks.append({'category':category,'topic':ts[i%len(ts)],'setting':settings[(i//len(ts))%len(settings)],'style':styles[rng.randrange(len(styles))],'angle':angles[rng.randrange(len(angles))],'turns':rng.choices([2,4,6],[10,65,25])[0],'variation_seed':rng.randrange(1,2**31)})
rng.shuffle(tasks)
for i,t in enumerate(tasks):t['slot']=i;t['scenario_id']=f'local-author-v1-{i:05d}'
assert len(tasks)==9800
out=root/'data/author-only-v1';out.mkdir(exist_ok=True)
(out/'existing-200.jsonl').write_bytes(src.read_bytes())
(out/'scenario-plan.json').write_text(json.dumps(tasks,indent=2)+'\n')
config={'version':'local-author-v1','target_total':10000,'existing_chat_authored':200,'local_teacher_target':9800,'category_targets':targets,'existing_category_counts':dict(counts),'teacher_repo':'mlx-community/Qwen3-4B-Instruct-2507-4bit','teacher_revision':'50d427756c6b1b2fe0c0a10f67fbda1fc8e82c1b','teacher_local_path':'data/local-teacher-qwen3-4b','sampling':{'temperature':0.7,'top_p':0.8,'top_k':20},'max_new_tokens':768,'attempts_per_slot':20,'student_context_limit':513,'cache_limit_bytes':268435456,'memory_limit_bytes':12884901888,'swap_growth_limit_mb':1024,'min_free_disk_bytes':16106127360,'battery_policy':'continue_on_battery','quality_review':'deferred_until_all_10000_generated','evaluation':'deferred_until_all_10000_generated','training_allowed':False,'paid_apis_allowed':False,'mechanical_checks_only':['valid JSON','exact alternating role count','nonempty content','complete EOS-finished teacher response','student context fit without truncation','exact duplicate conversation exclusion'],'input_hashes':{n:hashlib.sha256((out/n).read_bytes()).hexdigest() for n in ['existing-200.jsonl','scenario-plan.json']},'tokenizer_sha256':hashlib.sha256((root/'data/sft-v3/tokenizer.json').read_bytes()).hexdigest()}
(root/'configs/local_author_v1.json').write_text(json.dumps(config,indent=2)+'\n')
print('Prepared',len(tasks),'generation slots')
